                module Action
                module HandleSelectedRecordProximity
                ; Документация [алгоритм и проверка](../../Docs/ActionSelectedRecordProximity.md)
                ; -----------------------------------------
                ; Проверка выбранной записи, резервный поиск класса 8 и обработка близости
                ; исходная запись 17, адреса F04A..F074
                ; In:
                ;   HL, DE, BC и AF числовых аргументов не задают, IX указывает текущую FActionRecord
                ;   ProximityIndex задаёт полный байтовый индекс выбранной записи, ProximityClass требуемый полный ClassCode
                ;   читаются выбранные Components, ClassCode и ReuseByte, по текущей записи доступны компоненты, фазовые поля и TargetCodeStep
                ;   действуют условия SelectRecordByIndex, SelectClass8ForRecord, MaxRecordDeltaHigh и StepCodesTowardRecord
                ;   подготовлен ACTION банка 0 и числовые таблицы, 7FFD разблокирован, 18 дополнительных байтов CPU-стека доступны, IRQ не вмешиваются
                ;   читается Component0.High, для активной записи доступны остальные фазовые поля, класс, состояние и порог
                ;   OffsetScaleLow и OffsetScaleHigh активной записи доступны для записи, ACTION банка 0 и общая RAM доступны
                ;   действует договор ApplyObjectOffsetVector, шесть байтов под SP и внешний возврат не перекрывают его код, таблицы, операнды и результаты
                ;   IRQ и повторный вход исключены
                ; Out:
                ;   на границе F0F8 либо прямого ближнего RET HL на резервном пути сохраняется, на ближнем равен модулю третьей разности, на дальнем возвращается от StepCodesTowardRecord
                ;   на границе F0F8 либо прямого ближнего RET DE на резервном пути содержит D=08 и входной E, на ближнем равен модулю первой разности, на дальнем возвращается от шага фаз
                ;   на границе F0F8 либо прямого ближнего RET BC на резервном пути равен 0040, на ближнем сохраняет входное значение, на дальнем содержит два рассчитанных целевых кода
                ;   на границе F0F8 либо прямого ближнего RET AF на резервной границе F0F8 соответствует преобразованию найденного индекса либо 8042 при отсутствии класса 8, на ближнем A=максимум старших байтов модулей и F от CP с 2, на дальнем возвращается от шага фаз
                ;   на границе F0F8 либо прямого ближнего RET HL', DE', BC', AF' сохраняются без подвода кодов, на дальнем пути равны результату геометрии
                ;   на границе F0F8 либо прямого ближнего RET IX сохраняется, IY на резервном пути указывает класс 8 либо маркер, на ближнем и дальнем выбранную по ProximityIndex запись
                ;   I, IM и IFF сохраняются, без подвода paging сохраняется, на дальнем пути OUT 7FFD получает 11 и 10
                ;   выбранный IY=A100+64*ProximityIndex вычисляется без ограничения ёмкостью исходного массива, FF не получает особой трактовки
                ;   при Component0.High выбранной записи=80 либо несовпадении ClassCode с ProximityClass выполняется резервный SelectClass8ForRecord
                ;   резервный путь может обновить ProximityIndex, ProximityClass сохраняется даже после выбора другого класса
                ;   при подходящей записи и расстоянии меньше 2 сброшен бит 2 её ReuseByte, затем текущие Component0=8000 и ReuseByte=FF, внешний RET даёт SP=входной SP+2
                ;   резервный и дальний пути исполняют общий F0F8 до внешнего RET, последующие эффекты относятся только к этим ветвям
                ;   при Component0.High текущей записи=80 общий хвост возвращает AF=8042, остальные результаты префикса и собственные записи сохраняются, R добавляет четыре M1
                ;   на активной ветви нижеследующие результаты вычислителя относятся к V из прежнего OffsetScaleLow и выбранного старшего байта
                ;   HL=(-Q) AND FFFF при бите 7 S=1, иначе HL=Q, DE=Q при бите 7 S=1, иначе DE=abs(V)
                ;   BC - B=W[Offset0], C=0
                ;   AF - A=S, F от 16-разрядного 0-Q при бите 7 S=1, иначе флаги логического XOR с результатом S
                ;   HL', DE', BC' сохраняют результаты префикса
                ;   AF' - A'=U, F'=(U AND 28) OR (40 при U=0) OR (10 при 2*((P SHR 16) AND 0F)+(U AND 1)>0F), остальные биты F' нулевые
                ;   IX восстановлен, IYH сохраняет старший байт выбранной резервным поиском либо исходным селектором записи, IYL=W[(Offset1+64) AND FF]
                ;   Coefficient0..2 содержат результат построителя, Base0..2 содержат три произведения с одним входным V
                ;   SP=входной SP+2, I, IM, IFF и paging сохраняются, порты не используются
                ;   Offset0..2 получают OffsetPhase0, wrap8(OffsetPhase1+80) и OffsetPhase2
                ;   OffsetScaleLow получает wrap8(старое+1), если этот кандидат ниже Phase2OrTarget, иначе сохраняется прежний байт
                ;   OffsetScaleHigh обнулён при ClassCode<10 и StateCode не равном 13, иначе сохранён
                ;   на активной ветви R учитывает 30+Hold+4*Small+2*Small*Different M1 подготовки плюс полный вычислитель, старший бит R сохраняется
                ;   на всех путях SP=входной SP+2, IX, I/IM/IFF сохраняются, общий хвост дополнительных OUT не выполняет
                ;   собственный префикс получает 26+K8 M1 при недоступной цели, 31+K8 при другом классе, 44+Kdist на прямом ближнем RET и 64+Kdist+G+S на дальнем, в непрямых ветвях затем добавляется полный F0F8
                ;   максимальная временная рамка до 18 байтов, общий вычислитель последовательно использует шесть байтов после возврата детей
                ; Corrupt:
                ;   HL, DE, BC, AF, HL', DE', BC' на дальнем пути, AF' на активном общем пути, IY, R, ProximityIndex по резервному выбору, ReuseByte выбранной записи и поля освобождения по ближней ветви, фазы и масштабы по дальнему и общему путям
                ;   операнды геометрии, три фазовых операнда, Coefficient0..2, Base0..2, до 18 временных байтов CPU-стека, 7FFD только при дальнем подводе
                ; Note:
                ;   K8 означает полные M1 SelectClass8ForRecord до F0F8, дополнительные проверки требуемого класса дают пять M1
                ;   Kdist, G и S означают полные M1 MaxRecordDeltaHigh, EncodeHalfCoordinateDeltas и ApplyCodes, включая их RET
                ;   это исходный адрес State0D, проверяется только полный старший байт доступности 80, младший байт в первой проверке не читается
                ;   сравнение класса не является проверкой битовой маски, индекс 00..FF не ограничивается принадлежностью физическому исходному массиву
                ;   при IY=IX сначала сбрасывается бит 2, затем тот же ReuseByte получает FF, последнее значение FF сохранено
                ;   бит 2 имеет маску 04, его полная игровая роль среди других применений ReuseByte не объявляется установленной
                ;   1024 сценария проверили все 256 индексов, четыре профиля, самовыбор, оба резервных результата и обе ветви расстояния
                ;   за исходным массивом тест сохраняет оригинальные байты цели, включая находящийся там исполняемый код
                ;   все возможные данные записей, аппаратные IRQ, точные T, сборка и нативная игра не проверялись
                ;   прежняя серия 1024 случая проверяет границу F0F8 либо прямой RET, новая серия тех же профилей исполняет весь путь до внешнего RET
                ;   новая серия имеет 31 прямое освобождение и 993 общих хвоста, из них один маркер, 355 увеличений масштаба и 637 сохранений
                ;   сверены регистры кроме T, точный R и полное число M1, восемь банков, кратность присваиваний и реальные OUT, фазы и масштабы связаны с номером профиля
                ;   эффективное слово V перед 6D06 содержит прежний OffsetScaleLow в E и итоговый OffsetScaleHigh в D, это не входное DE всей процедуры
                ;   Hold=1 при сохранении прежнего младшего масштаба, иначе 0, Small=1 при ClassCode<10, Different=1 при StateCode не равном 13, иначе соответствующий признак нулевой
                ;   10, 13 и 80 в условиях полей обозначают шестнадцатеричные коды, числа M1 десятичные
                ;   c2 обозначает третий байтовый коэффициент, m=abs(s8(c2)) AND 7F, P=m*abs(V), Q=floor(P/128), U=P SHR 15, S=c2 XOR HIGH слова V
                ;   нулевой фактор для коэффициента 80 сохранён, знак определяется исходным байтом коэффициента и старшим байтом V
                ;   каждое Base равно -floor((abs(s8(c_i)) AND 7F)*abs(V)/128) при бите 7 c_i XOR HIGH V, иначе положительному частному, всё по модулю 65536
                ;   шесть временных байтов после возврата содержат исходный IX по SP-2, слово V по SP-4 и внутренний возврат 6D0C по SP-6, POP не очищает RAM
                ;   для фактора m>0 умножение даёт 35+floor(log2(m))+2*popcount(m) M1, при m=0 даёт 32 M1
                ;   к каждому умножению добавляются семь M1 при V<0, две при бите 7 коэффициента и четыре при бите 7 его XOR HIGH V
                ; -----------------------------------------
                ; Выбор адреса по полному байтовому индексу ProximityIndex, ограничение числом исходных слотов отсутствует.
Entry:          LD A, (IX + @FActionRecord.ProximityIndex)
                CALL @Action.SelectRecordByIndex.Entry
                ; Проверка доступности выбранной записи по полному старшему байту первой компоненты.
                LD A, (IY + @FActionRecord.Components.Component0.High)
                CP @ActionReuseConst.ReusableHigh
                JP Z, @Action.SelectClass8ForRecord.Entry                       ; переход, если старший байт выбранной первой компоненты равен 80, выполнить резервный поиск класса 8

                ; Проверка полного класса выбранной записи относительно требуемого ProximityClass.
                LD A, (IY + @FActionRecord.ClassCode)
                CP (IX + @FActionRecord.ProximityClass)
                JP NZ, @Action.SelectClass8ForRecord.Entry                      ; переход, если полный ClassCode не совпал с ProximityClass, выполнить резервный поиск класса 8

                ; Расчёт максимума старших байтов модулей трёх обёрнутых разностей выбранной и текущей записей.
                CALL @Action.MaxRecordDeltaHigh.Entry
                ; Проверка близости по общему порогу модулей меньше 512.
                CP @ActionClass18ProximityConst.NearLimit
                JR NC, @Action.HandleSelectedRecordProximity.StepFar            ; переход, если максимальный старший байт не меньше двух, подвести фазовые коды к выбранной записи

                ; Обновление выбранного ReuseByte, сброс только бита 2 с сохранением всех остальных разрядов.
                RES @ActionSelectedRecordProximityConst.ClearedReuseBit, (IY + @FActionRecord.ReuseByte)
                ; Освобождение текущей записи с внешним RET, при совпадении указателей её ReuseByte окончательно станет FF.
                JP @Action.MarkRecordForReuse.Entry

                ; Подвод двух фазовых кодов текущей записи через настоящую цепочку геометрии и шага.
StepFar:        CALL @Action.StepCodesTowardRecord.Entry
                ; Передача общему подготовителю смещений с исходным внешним CPU-стеком.
                JP @Action.PrepareObjectOffsetTransform.Entry

                endmodule
                endmodule
